#include <iostream>
struct Tracker {
    int id;
    Tracker(int i) : id(i) { std::cout << "Ctor" << id << " "; }
    Tracker(const Tracker& other) : id(other.id) { std::cout << "Copy" << id << " "; }
    ~Tracker() { std::cout << "Dtor" << id << " "; }
};

void byValue(Tracker t) {
    std::cout << "In" << t.id << " ";
}

int main() {
    Tracker a(1);
    byValue(a);
    std::cout << "End ";
}

Also state exactly how many times the destructor runs and why.

