questions.question:
Trace the standard Insertion Sort implementation below on the array [5, 3, 8, 4, 2]. Report the exact total number of element comparisons (only 'A[j] > key' checks count; the 'j >= 0' bound check does not):

void insertionSort(int A[], int n) {
    for (int i = 1; i < n; i++) {
        int key = A[i];
        int j = i - 1;
        while (j >= 0 && A[j] > key) {
            A[j + 1] = A[j];
            j--;
        }
        A[j + 1] = key;
    }
}

questions.expected_output_code:
#include <iostream>
int insertionSortCount(int A[], int n) {
    int comparisons = 0;
    for (int i = 1; i < n; i++) {
        int key = A[i];
        int j = i - 1;
        while (j >= 0 && (++comparisons, A[j] > key)) {
            A[j + 1] = A[j];
            j--;
        }
        A[j + 1] = key;
    }
    return comparisons;
}
int main() {
    int A[] = {5, 3, 8, 4, 2};
    int c = insertionSortCount(A, 5);
    std::cout << c << std::endl; // 9
    for (int x : A) std::cout << x << " "; // 2 3 4 5 8
}
